def subtract(a, b):
    # Filter out empty intervals and normalize
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []
    if not b_intervals:
        return a_intervals

    # Merge overlapping intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1] = [merged_b[-1][0], max(merged_b[-1][1], end)]
        else:
            merged_b.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_intervals:
        current = a_start
        for b_start, b_end in merged_b:
            if current >= a_end:
                break
            if b_end <= current:
                continue
            if b_start >= a_end:
                break

            # Add the part before b_start
            if current < b_start:
                if len(result) > 0 and result[-1][1] == current:
                    result[-1][1] = b_start
                else:
                    result.append([current, b_start])

            # Move current past this b interval
            current = max(current, b_end)

        # Add remaining part of a interval
        if current < a_end:
            if len(result) > 0 and result[-1][1] == current:
                result[-1][1] = a_end
            else:
                result.append([current, a_end])

    return result

